import{_ as p,a0 as r,w as o,s as d,I as a,x as e,a1 as t,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"PostgreSQL 入门 | LCTT x X-CMD","titleTemplate":false,"description":"PostgreSQL 入门 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PostgreSQL 入门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PostgreSQL 入门 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191112 Getting started with PostgreSQL","title":"PostgreSQL 入门","tag":"201911","desc":""},"relativePath":"201911/20191112 Getting started with PostgreSQL.md","filePath":"[post].md"}'),g={name:"201911/20191112 Getting started with PostgreSQL.md"};function h(c,s,k,u,b,f){const i=r("Link");return o(),d("div",null,[s[21]||(s[21]=a("h1",{id:"postgresql-入门",tabindex:"-1"},[e("PostgreSQL 入门 "),a("a",{class:"header-anchor",href:"#postgresql-入门","aria-label":"Permalink to “PostgreSQL 入门”"},"​")],-1)),s[22]||(s[22]=a("blockquote",null,[a("p",null,"安装、设置、创建和开始使用 PostgreSQL 数据库。")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/201911/20/085936u10q7eme1euu4ak3.jpg",alt:""})],-1)),s[24]||(s[24]=a("p",null,"每个人或许都有需要在数据库中保存的东西。即使你执着于使用纸质文件或电子文件，它们也会变得很麻烦。纸质文档可能会丢失或混乱，你需要访问的电子信息可能会隐藏在段落和页面的深处。",-1)),a("p",null,[s[1]||(s[1]=e("在我从事医学工作的时候，我使用 ",-1)),t(i,{href:"https://www.postgresql.org/"},{default:n(()=>[...s[0]||(s[0]=[e("PostgreSQL",-1)])]),_:1}),s[2]||(s[2]=e(" 来跟踪我的住院患者名单并提交有关住院患者的信息。我将我的每日患者名单打印在口袋里，以便快速了解患者房间、诊断或其他细节的任何变化并做出快速记录。",-1))]),s[25]||(s[25]=l('<p>我以为一切没问题，直到去年我妻子决定买一辆新车，我“接手”了她以前的那辆车。她保留了汽车维修和保养服务收据的文件夹，但随着时间的流逝，它变得杂乱。与其花时间筛选所有纸条以弄清楚什么时候做了什么，我认为 PostgreSQL 将是更好的跟踪此信息的方法。</p><h3 id="安装-postgresql" tabindex="-1">安装 PostgreSQL <a class="header-anchor" href="#安装-postgresql" aria-label="Permalink to “安装 PostgreSQL”">​</a></h3><p>自上次使用 PostgreSQL 以来已经有一段时间了，我已经忘记了如何使用它。实际上，我甚至没有在计算机上安装它。安装它是第一步。我使用 Fedora，因此在控制台中运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf list postgresql*</span></span></code></pre></div><p>请注意，你无需使用 <code>sudo</code> 即可使用 <code>list</code> 选项。该命令返回了很长的软件包列表。看了眼后，我决定只需要三个：postgresql、postgresql-server 和 postgresql-docs。</p>',5)),a("p",null,[s[4]||(s[4]=e("为了了解下一步需要做什么，我决定查看 ",-1)),t(i,{href:"http://www.postgresql.org/docs"},{default:n(()=>[...s[3]||(s[3]=[e("PostgreSQL 文档",-1)])]),_:1}),s[5]||(s[5]=e("。文档参考内容非常丰富，实际上，丰富到令人生畏。幸运的是，我发现我在升级 Fedora 时曾经做过的一些笔记，希望有效地导出数据库，在新版本上重新启动 PostgreSQL，以及导入旧数据库。",-1))]),s[26]||(s[26]=l(`<h3 id="设置-postgresql" tabindex="-1">设置 PostgreSQL <a class="header-anchor" href="#设置-postgresql" aria-label="Permalink to “设置 PostgreSQL”">​</a></h3><p>与大多数其他软件不同，你不能只是安装好 PostgreSQL 就开始使用它。你必须预先执行两个基本步骤：首先，你需要设置 PostgreSQL，第二，你需要启动它。你必须以 <code>root</code> 用户身份执行这些操作（<code>sudo</code> 在这里不起作用）。</p><p>要设置它，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>postgresql-setup –initdb</span></span></code></pre></div><p>这将确定 PostgreSQL 数据库在计算机上的位置。然后（仍为 <code>root</code>）输入以下两个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start postgresql.service</span></span>
<span class="line"><span>systemctl enable postgresql.service</span></span></code></pre></div><p>第一个命令为当前会话启动 PostgreSQL（如果你关闭机器，那么 PostgreSQL 也将关闭）。第二个命令使 PostgreSQL 在随后的重启中自动启动。</p><h3 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to “创建用户”">​</a></h3><p>PostgreSQL 正在运行，但是你仍然不能使用它，因为你还没有用户。为此，你需要切换到特殊用户 <code>postgres</code>。当你仍以 <code>root</code> 身份运行时，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>su postgres</span></span></code></pre></div><p>由于你是以 <code>root</code> 的身份执行此操作的，因此无需输入密码。root 用户可以在不知道密码的情况下以任何用户身份操作；这就是使其强大而危险的原因之一。</p><p>现在你就是 <code>postgres</code> 了，请运行下面两个命令，如下所示创建用户（创建用户 <code>gregp</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>createuser gregp</span></span>
<span class="line"><span>createdb gregp</span></span></code></pre></div><p>你可能会看到错误消息，如：<code>Could not switch to /home/gregp</code>。这只是意味着用户 <code>postgres</code>不能访问该目录。尽管如此，你的用户和数据库已创建。接下来，输入 <code>exit</code> 并按回车两次，这样就回到了原来的用户下（<code>root</code>）。</p><h3 id="设置数据库" tabindex="-1">设置数据库 <a class="header-anchor" href="#设置数据库" aria-label="Permalink to “设置数据库”">​</a></h3><p>要开始使用 PostgreSQL，请在命令行输入 <code>psql</code>。你应该在每行左侧看到类似 <code>gregp=&gt;</code> 的内容，以显示你使用的是 PostgreSQL，并且只能使用它理解的命令。你自动获得一个数据库（我的名为 <code>gregp</code>），它里面完全没有内容。对 PostgreSQL 来说，数据库只是一个工作空间。在空间内，你可以创建<em>表</em>。表包含变量列表，而表中的每个变量是构成数据库的数据。</p><p>以下是我设置汽车服务数据库的方式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE TABLE autorepairs (</span></span>
<span class="line"><span>        date            date,</span></span>
<span class="line"><span>        repairs         varchar(80),</span></span>
<span class="line"><span>        location        varchar(80),</span></span>
<span class="line"><span>        cost            numeric(6,2)</span></span>
<span class="line"><span>);</span></span></code></pre></div><p>我本可以在一行内输入，但为了更好地说明结构，并表明 PostgreSQL 不会解释制表符和换行的空白，我分成了多行。字段包含在括号中，每个变量名和数据类型与下一个变量用逗号分隔（最后一个除外），命令以分号结尾。所有命令都必须以分号结尾！</p><p>第一个变量名是 <code>date</code>，它的数据类型也是 <code>date</code>，这在 PostgreSQL 中没关系。第二个和第三个变量 <code>repairs</code> 和 <code>location</code> 都是 <code>varchar(80)</code> 类型，这意味着它们可以是最多 80 个任意字符（字母、数字等）。最后一个变量 <code>cost</code> 使用 <code>numeric</code> 类型。括号中的数字表示最多有六位数字，其中两位是小数。最初，我尝试了 <code>real</code> 类型，这将是一个浮点数。<code>real</code> 类型的问题是作为数据类型在使用时，在遇到 <code>WHERE</code> 子句，类似 <code>WHERE cost = 0</code> 或其他任何特定数字。由于 <code>real</code> 值有些不精确，因此特定数字将永远不会匹配。</p><h3 id="输入数据" tabindex="-1">输入数据 <a class="header-anchor" href="#输入数据" aria-label="Permalink to “输入数据”">​</a></h3><p>接下来，你可以使用 <code>INSERT INTO</code> 命令添加一些数据（在 PostgreSQL 中称为<em>行</em>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INSERT INTO autorepairs VALUES (&#39;2017-08-11&#39;, &#39;airbag recall&#39;, &#39;dealer&#39;, 0);</span></span></code></pre></div><p>请注意，括号构成了一个值的容器，它必须以正确的顺序，用逗号分隔，并在命令末尾加上分号。<code>date</code> 和 <code>varchar(80)</code> 类型的值必须包含在单引号中，但数字值（如 <code>numeric</code>）不用。作为反馈，你应该会看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>INSERT 0 1</span></span></code></pre></div><p>与常规终端会话一样，你会有输入命令的历史记录，因此，在输入后续行时，通常可以按向上箭头键来显示最后一个命令并根据需要编辑数据，从而节省大量时间。</p><p>如果出了什么问题怎么办？使用 <code>UPDATE</code> 更改值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UPDATE autorepairs SET date = &#39;2017-11-08&#39; WHERE repairs = &#39;airbag recall&#39;;</span></span></code></pre></div><p>或者，也许你不再需要表中的行。使用 <code>DELETE</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE FROM autorepairs WHERE repairs = &#39;airbag recall&#39;;</span></span></code></pre></div><p>这将删除整行。</p><p>最后一件事：即使我在 PostgreSQL 命令中一直使用大写字母（在大多数文档中也这么做），你也可以用小写字母输入，我也经常如此。</p><h3 id="输出数据" tabindex="-1">输出数据 <a class="header-anchor" href="#输出数据" aria-label="Permalink to “输出数据”">​</a></h3><p>如果你想展示数据，使用 <code>SELECT</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT * FROM autorepairs ORDER BY date;</span></span></code></pre></div><p>没有 <code>ORDER BY</code> 的话，行将不管你输入的内容来显示。例如，以下就是我终端中输出的我的汽车服务数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SELECT date, repairs FROM autorepairs ORDER BY date;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    date   |                             repairs                             </span></span>
<span class="line"><span>-----------+-----------------------------------------------------------------</span></span>
<span class="line"><span>2008-08-08 | oil change, air filter, spark plugs</span></span>
<span class="line"><span>2011-09-30 | 35000 service, oil change, rotate tires/balance wheels</span></span>
<span class="line"><span>2012-03-07 | repl battery</span></span>
<span class="line"><span>2012-11-14 | 45000 maint, oil/filter</span></span>
<span class="line"><span>2014-04-09 | 55000 maint, oil/filter, spark plugs, air/dust filters</span></span>
<span class="line"><span>2014-04-21 | replace 4 tires</span></span>
<span class="line"><span>2014-04-21 | wheel alignment</span></span>
<span class="line"><span>2016-06-01 | 65000 mile service, oil change</span></span>
<span class="line"><span>2017-05-16 | oil change, replce oil filt housing</span></span>
<span class="line"><span>2017-05-26 | rotate tires</span></span>
<span class="line"><span>2017-06-05 | air filter, cabin filter,spark plugs</span></span>
<span class="line"><span>2017-06-05 | brake pads and rotors, flush brakes</span></span>
<span class="line"><span>2017-08-11 | airbag recall</span></span>
<span class="line"><span>2018-07-06 | oil/filter change, fuel filter, battery svc</span></span>
<span class="line"><span>2018-07-06 | transmission fl, p steering fl, rear diff fl</span></span>
<span class="line"><span>2019-07-22 | oil &amp;amp; filter change, brake fluid flush, front differential flush</span></span>
<span class="line"><span>2019-08-20 | replace 4 tires</span></span>
<span class="line"><span>2019-10-09 | replace passenger taillight bulb</span></span>
<span class="line"><span>2019-10-25 | replace passenger taillight assembly</span></span>
<span class="line"><span>(19 rows)</span></span></code></pre></div><p>要将此发送到文件，将输出更改为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\o autorepairs.txt</span></span></code></pre></div><p>然后再次运行 <code>SELECT</code> 命令。</p><h3 id="退出-postgresql" tabindex="-1">退出 PostgreSQL <a class="header-anchor" href="#退出-postgresql" aria-label="Permalink to “退出 PostgreSQL”">​</a></h3><p>最后，在终端中退出 PostgreSQL，输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>quit</span></span></code></pre></div><p>或者它的缩写版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\\q</span></span></code></pre></div><p>虽然这只是 PostgreSQL 的简要介绍，但我希望它展示了将数据库用于这样的简单任务既不困难也不费时。</p><hr>`,47)),a("p",null,[s[7]||(s[7]=e("via: ",-1)),t(i,{href:"https://opensource.com/article/19/11/getting-started-postgresql"},{default:n(()=>[...s[6]||(s[6]=[e("https://opensource.com/article/19/11/getting-started-postgresql",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=e("作者：",-1)),t(i,{href:"https://opensource.com/users/greg-p"},{default:n(()=>[...s[8]||(s[8]=[e("Greg Pittman",-1)])]),_:1}),s[13]||(s[13]=e(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[9]||(s[9]=[e("lujun9972",-1)])]),_:1}),s[14]||(s[14]=e(" 译者：",-1)),t(i,{href:"https://github.com/geekpi"},{default:n(()=>[...s[10]||(s[10]=[e("geekpi",-1)])]),_:1}),s[15]||(s[15]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[18]||(s[18]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[16]||(s[16]=[e("LCTT",-1)])]),_:1}),s[19]||(s[19]=e(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:n(()=>[...s[17]||(s[17]=[e("Linux中国",-1)])]),_:1}),s[20]||(s[20]=e(" 荣誉推出",-1))])])}const S=p(g,[["render",h]]);export{P as __pageData,S as default};
